-- xBike MRP data model v3.1 — 31/10/2026. PostgreSQL 15+.
-- Gộp TonKho vào MatHang theo xbike_mrp_data_model_v3.1.dbml.
-- Khởi tạo CSDL trống; không phải migration, không DROP dữ liệu hiện có.
-- Chạy init.sql trước seed.sql. Lỗi bất kỳ sẽ rollback toàn file.
BEGIN;
SET LOCAL TIME ZONE 'Asia/Ho_Chi_Minh';
SET LOCAL search_path = public, pg_catalog;

CREATE TABLE "NhanVien" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "vai_tro_id" int NOT NULL,
  "ten_dang_nhap" varchar UNIQUE NOT NULL,
  "mat_khau" varchar NOT NULL,
  "ma_nhan_vien" varchar UNIQUE NOT NULL,
  "ho_ten" varchar,
  "ngay_sinh" date,
  "so_dien_thoai" varchar,
  "email" varchar,
  "ngay_vao_lam" date,
  "he_so_luong" decimal(5,2),
  "trang_thai" varchar NOT NULL DEFAULT 'hoat_dong',
  CONSTRAINT "ck_nhan_vien_trang_thai" CHECK (trang_thai IN ('hoat_dong', 'bi_khoa')),
  CONSTRAINT "ck_nhan_vien_he_so_luong" CHECK (he_so_luong >= 0),
  CONSTRAINT "ck_nhan_vien_ma" CHECK (ma_nhan_vien ~ '^NV-[0-9]{6}$' AND right(ma_nhan_vien, 6) <> '000000')
);

CREATE TABLE "VaiTro" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ma_vai_tro" varchar UNIQUE NOT NULL,
  "ten_vai_tro" varchar NOT NULL,
  "mo_ta" varchar(255),
  CONSTRAINT "ck_vai_tro_ma_vai_tro" CHECK (ma_vai_tro IN ('nhan_vien', 'quan_ly', 'quan_tri_vien'))
);

CREATE TABLE "MatHang" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ma_mat_hang" varchar UNIQUE NOT NULL,
  "ten_mat_hang" varchar NOT NULL,
  "sku" varchar UNIQUE NOT NULL,
  "loai_mat_hang" varchar NOT NULL,
  "don_vi_tinh" varchar NOT NULL,
  "mau_sac" varchar,
  "mo_ta" varchar,
  "don_gia" bigint NOT NULL,
  "is_active" bool NOT NULL DEFAULT true,
  "so_luong_ton" int NOT NULL DEFAULT 0,
  "ton_kho_updated_at" timestamptz,
  CONSTRAINT "ck_mat_hang_so_luong_ton" CHECK (so_luong_ton >= 0),
  CONSTRAINT "ck_mat_hang_loai_mat_hang" CHECK (loai_mat_hang IN ('nguyen_vat_lieu', 'linh_kien', 'ban_thanh_pham', 'thanh_pham')),
  CONSTRAINT "ck_mat_hang_don_gia" CHECK (don_gia >= 0),
  CONSTRAINT "ck_mat_hang_ten" CHECK (ten_mat_hang ~ '[^[:space:]]'),
  CONSTRAINT "ck_mat_hang_ma" CHECK (ma_mat_hang ~ '^MH-[0-9]{6}$' AND right(ma_mat_hang, 6) <> '000000')
);

-- Delivered only after commit. Readers reload committed rows using a separate session.
CREATE FUNCTION thong_bao_mat_hang_thay_doi() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  PERFORM pg_notify('mat_hang_changed', '');
  RETURN NULL;
END;
$$;

CREATE TRIGGER trg_mat_hang_thay_doi
AFTER INSERT OR UPDATE OR DELETE ON "MatHang"
FOR EACH STATEMENT EXECUTE FUNCTION thong_bao_mat_hang_thay_doi();

CREATE TABLE "Bom" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "mat_hang_id" int NOT NULL,
  "version" int NOT NULL,
  "start_time" timestamptz,
  "end_time" timestamptz,
  "is_active" bool NOT NULL DEFAULT true,
  CONSTRAINT "ck_bom_version" CHECK (version > 0),
  CONSTRAINT "ck_bom_thoi_gian" CHECK (end_time IS NULL OR (start_time IS NOT NULL AND end_time > start_time))
);

CREATE TABLE "ChiTietBom" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "bom_id" int NOT NULL,
  "mat_hang_id" int NOT NULL,
  "so_luong" int NOT NULL,
  CONSTRAINT "ck_chi_tiet_bom_so_luong" CHECK (so_luong > 0)
);

CREATE TABLE "NhaCungCap" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ma_ncc" varchar UNIQUE NOT NULL,
  "ten_ncc" varchar,
  "so_dien_thoai" varchar,
  "dia_chi" varchar,
  "phuong" varchar,
  "tinh" varchar,
  CONSTRAINT "ck_nha_cung_cap_ma" CHECK (ma_ncc ~ '^NCC-[0-9]{6}$' AND right(ma_ncc, 6) <> '000000')
);

CREATE TABLE "PhieuNhap" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ma_phieu_nhap" varchar UNIQUE NOT NULL,
  "nhan_vien_id" int NOT NULL,
  "ncc_id" int NOT NULL,
  "ngay_nhap" date NOT NULL,
  "ghi_chu" text,
  "tong_tien" numeric(18,2),
  "trang_thai" varchar NOT NULL DEFAULT 'nhap',
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  CONSTRAINT "ck_phieu_nhap_trang_thai" CHECK (trang_thai IN ('nhap', 'hoan_thanh')),
  CONSTRAINT "ck_phieu_nhap_tien" CHECK (tong_tien >= 0),
  CONSTRAINT "ck_phieu_nhap_ma" CHECK (ma_phieu_nhap ~ '^PN-[0-9]{4}(0[1-9]|1[0-2])-[0-9]{6}$' AND right(ma_phieu_nhap, 6) <> '000000')
);

CREATE TABLE "ChiTietPhieuNhap" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "phieu_nhap_id" int NOT NULL,
  "mat_hang_id" int NOT NULL,
  "so_luong" int NOT NULL,
  "don_gia_thuc" numeric(18,2),
  "tong_gia" numeric(18,2),
  CONSTRAINT "ck_chi_tiet_phieu_nhap_so_luong" CHECK (so_luong > 0),
  CONSTRAINT "ck_chi_tiet_phieu_nhap_tien" CHECK (don_gia_thuc >= 0 AND tong_gia >= 0)
);

CREATE TABLE "PhieuXuat" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ma_phieu_xuat" varchar UNIQUE NOT NULL,
  "nhan_vien_id" int NOT NULL,
  "loai_phieu" varchar NOT NULL,
  "yeu_cau_san_xuat_id" int,
  "lenh_san_xuat_id" int,
  "tong_tien" bigint,
  "trang_thai" varchar NOT NULL DEFAULT 'nhap',
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  CONSTRAINT "ck_phieu_xuat_trang_thai" CHECK (trang_thai IN ('nhap', 'cho_duyet', 'da_duyet', 'tu_choi')),
  CONSTRAINT "ck_phieu_xuat_loai_phieu" CHECK (loai_phieu IN ('xuat_vat_tu', 'xuat_thanh_pham')),
  CONSTRAINT "ck_phieu_xuat_tien" CHECK (tong_tien >= 0),
  CONSTRAINT "ck_phieu_xuat_nguon" CHECK ((loai_phieu = 'xuat_vat_tu' AND lenh_san_xuat_id IS NOT NULL AND yeu_cau_san_xuat_id IS NULL) OR (loai_phieu = 'xuat_thanh_pham' AND yeu_cau_san_xuat_id IS NOT NULL AND lenh_san_xuat_id IS NULL)),
  CONSTRAINT "ck_phieu_xuat_ma" CHECK (ma_phieu_xuat ~ '^PX-[0-9]{4}(0[1-9]|1[0-2])-[0-9]{6}$' AND right(ma_phieu_xuat, 6) <> '000000')
);

CREATE TABLE "ChiTietPhieuXuat" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "phieu_xuat_id" int NOT NULL,
  "mat_hang_id" int NOT NULL,
  "so_luong" int NOT NULL,
  "don_gia_thuc" bigint,
  "tong_gia" bigint,
  CONSTRAINT "ck_chi_tiet_phieu_xuat_so_luong" CHECK (so_luong > 0),
  CONSTRAINT "ck_chi_tiet_phieu_xuat_tien" CHECK (don_gia_thuc >= 0 AND tong_gia >= 0)
);

CREATE TABLE "YeuCauSanXuat" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ma_yeu_cau_san_xuat" varchar UNIQUE NOT NULL,
  "mat_hang_id" int NOT NULL,
  "so_luong" int NOT NULL,
  "nhan_vien_id" int NOT NULL,
  "nhan_vien_duoc_giao_id" int,
  "trang_thai" varchar NOT NULL DEFAULT 'nhap',
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "completed_at" timestamptz,
  CONSTRAINT "ck_yeu_cau_san_xuat_trang_thai" CHECK (trang_thai IN ('nhap', 'da_gui', 'cho_bo_sung_vat_tu', 'dang_thuc_hien', 'hoan_thanh', 'da_huy')),
  CONSTRAINT "ck_yeu_cau_san_xuat_so_luong" CHECK (so_luong > 0),
  CONSTRAINT "ck_yeu_cau_nguoi_duoc_giao" CHECK (trang_thai IN ('nhap','da_huy') OR nhan_vien_duoc_giao_id IS NOT NULL),
  CONSTRAINT "ck_yeu_cau_san_xuat_ma" CHECK (ma_yeu_cau_san_xuat ~ '^YCSX-[0-9]{4}(0[1-9]|1[0-2])-[0-9]{6}$' AND right(ma_yeu_cau_san_xuat, 6) <> '000000')
);

CREATE TABLE "LenhSanXuat" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ma_lenh_san_xuat" varchar UNIQUE NOT NULL,
  "yeu_cau_san_xuat_id" int NOT NULL,
  "lenh_san_xuat_cha_id" int,
  "mat_hang_id" int NOT NULL,
  "bom_id" int NOT NULL,
  "so_luong" int NOT NULL,
  "nhan_vien_id" int,
  "trang_thai" varchar NOT NULL DEFAULT 'nhap',
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "started_at" timestamptz,
  "completed_at" timestamptz,
  CONSTRAINT "ck_lenh_san_xuat_trang_thai" CHECK (trang_thai IN ('nhap', 'da_gui', 'dang_thuc_hien', 'hoan_thanh', 'da_huy')),
  CONSTRAINT "ck_lenh_san_xuat_so_luong" CHECK (so_luong > 0),
  CONSTRAINT "ck_lenh_khong_tu_lam_cha" CHECK (lenh_san_xuat_cha_id IS NULL OR lenh_san_xuat_cha_id <> id),
  CONSTRAINT "ck_lenh_nguoi_thuc_hien" CHECK (trang_thai IN ('nhap','da_huy') OR nhan_vien_id IS NOT NULL),
  CONSTRAINT "ck_lenh_san_xuat_ma" CHECK (ma_lenh_san_xuat ~ '^LSX-[0-9]{4}(0[1-9]|1[0-2])-[0-9]{6}$' AND right(ma_lenh_san_xuat, 6) <> '000000')
);

CREATE TABLE "ChiTietLenhSanXuat" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "lenh_san_xuat_id" int NOT NULL,
  "mat_hang_id" int NOT NULL,
  "so_luong_can" int NOT NULL,
  CONSTRAINT "ck_chi_tiet_lenh_san_xuat_so_luong_can" CHECK (so_luong_can > 0)
);

CREATE TABLE "ChungTuHoanThanhSx" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ma_phieu" varchar UNIQUE NOT NULL,
  "lenh_san_xuat_id" int NOT NULL,
  "so_luong_hoan_thanh" int NOT NULL,
  "nhan_vien_id" int NOT NULL,
  "trang_thai" varchar NOT NULL DEFAULT 'nhap',
  "finish_time" timestamptz,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  CONSTRAINT "ck_chung_tu_hoan_thanh_sx_trang_thai" CHECK (trang_thai IN ('nhap', 'cho_duyet', 'da_duyet', 'tu_choi')),
  CONSTRAINT "ck_chung_tu_hoan_thanh_sx_so_luong_hoan_thanh" CHECK (so_luong_hoan_thanh > 0),
  CONSTRAINT "ck_chung_tu_hoan_thanh_sx_ma" CHECK (ma_phieu ~ '^HTSX-[0-9]{4}(0[1-9]|1[0-2])-[0-9]{6}$' AND right(ma_phieu, 6) <> '000000')
);

CREATE TABLE "PhieuDieuChinhKho" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ma_phieu" varchar UNIQUE NOT NULL,
  "phieu_nhap_id" int NOT NULL,
  "nhan_vien_id" int NOT NULL,
  "ly_do" text NOT NULL,
  "trang_thai" varchar NOT NULL DEFAULT 'nhap',
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "confirmed_at" timestamptz,
  CONSTRAINT "ck_phieu_dieu_chinh_kho_trang_thai" CHECK (trang_thai IN ('nhap', 'da_xac_nhan', 'loi')),
  CONSTRAINT "ck_dieu_chinh_ly_do" CHECK (btrim(ly_do) <> ''),
  CONSTRAINT "ck_dieu_chinh_xac_nhan" CHECK ((trang_thai = 'da_xac_nhan' AND confirmed_at IS NOT NULL AND confirmed_at >= created_at) OR (trang_thai <> 'da_xac_nhan' AND confirmed_at IS NULL)),
  CONSTRAINT "ck_phieu_dieu_chinh_kho_ma" CHECK (ma_phieu ~ '^DCK-[0-9]{4}(0[1-9]|1[0-2])-[0-9]{6}$' AND right(ma_phieu, 6) <> '000000')
);

CREATE TABLE "ChiTietPhieuDieuChinhKho" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "phieu_dieu_chinh_kho_id" int NOT NULL,
  "mat_hang_id" int NOT NULL,
  "giao_dich_goc_id" int NOT NULL,
  "so_luong_hieu_luc_truoc" int NOT NULL,
  "so_luong_dung" int NOT NULL,
  "so_luong_bien_dong" int NOT NULL,
  CONSTRAINT "ck_chi_tiet_phieu_dieu_chinh_kho_luong" CHECK (so_luong_hieu_luc_truoc >= 0 AND so_luong_dung >= 0 AND so_luong_bien_dong <> 0 AND so_luong_bien_dong = so_luong_dung - so_luong_hieu_luc_truoc)
);

CREATE TABLE "TicketLoiDieuChinh" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ma_ticket" varchar UNIQUE NOT NULL,
  "phieu_nhap_id" int NOT NULL,
  "nguoi_tao_id" int NOT NULL,
  "mo_ta_loi" text NOT NULL,
  "trang_thai" varchar NOT NULL DEFAULT 'cho_xu_ly',
  "nguoi_xu_ly_id" int,
  "ket_qua_xu_ly" text,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "closed_at" timestamptz,
  CONSTRAINT "ck_ticket_loi_dieu_chinh_trang_thai" CHECK (trang_thai IN ('cho_xu_ly', 'dang_xu_ly', 'da_xu_ly')),
  CONSTRAINT "ck_ticket_mo_ta" CHECK (btrim(mo_ta_loi) <> ''),
  CONSTRAINT "ck_ticket_nguoi_xu_ly" CHECK (trang_thai = 'cho_xu_ly' OR nguoi_xu_ly_id IS NOT NULL),
  CONSTRAINT "ck_ticket_dong" CHECK ((trang_thai = 'da_xu_ly' AND nguoi_xu_ly_id IS NOT NULL AND ket_qua_xu_ly IS NOT NULL AND btrim(ket_qua_xu_ly) <> '' AND closed_at IS NOT NULL AND closed_at >= created_at) OR (trang_thai <> 'da_xu_ly' AND closed_at IS NULL)),
  CONSTRAINT "ck_ticket_loi_dieu_chinh_ma" CHECK (ma_ticket ~ '^TKDC-[0-9]{4}(0[1-9]|1[0-2])-[0-9]{6}$' AND right(ma_ticket, 6) <> '000000')
);

CREATE TABLE "ChiTietTicketLoiDieuChinh" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ticket_id" int NOT NULL,
  "chi_tiet_phieu_nhap_id" int NOT NULL,
  "mat_hang_id" int NOT NULL,
  "so_luong_hieu_luc_truoc" int NOT NULL,
  "so_luong_de_nghi" int NOT NULL,
  "so_luong_bien_dong" int NOT NULL,
  "ton_kho_tai_thoi_diem" int NOT NULL,
  CONSTRAINT "ck_chi_tiet_ticket_loi_dieu_chinh_luong" CHECK (so_luong_hieu_luc_truoc >= 0 AND so_luong_de_nghi >= 0 AND so_luong_bien_dong <> 0 AND so_luong_bien_dong = so_luong_de_nghi - so_luong_hieu_luc_truoc),
  CONSTRAINT "ck_ticket_ton_chup" CHECK (ton_kho_tai_thoi_diem >= 0)
);

CREATE TABLE "GiaoDichKho" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "mat_hang_id" int NOT NULL,
  "loai_giao_dich" varchar NOT NULL,
  "so_luong_bien_dong" int NOT NULL,
  "chi_tiet_phieu_nhap_id" int UNIQUE,
  "chi_tiet_phieu_xuat_id" int UNIQUE,
  "chung_tu_hoan_thanh_sx_id" int UNIQUE,
  "chi_tiet_phieu_dieu_chinh_id" int UNIQUE,
  "nhan_vien_id" int NOT NULL,
  "posted_at" timestamptz NOT NULL DEFAULT (now()),
  CONSTRAINT "ck_giao_dich_kho_loai_giao_dich" CHECK (loai_giao_dich IN ('nhap_vat_tu', 'xuat_vat_tu', 'nhap_san_pham_san_xuat', 'xuat_thanh_pham', 'dieu_chinh_ton_kho')),
  CONSTRAINT "ck_giao_dich_mot_nguon" CHECK (num_nonnulls(chi_tiet_phieu_nhap_id, chi_tiet_phieu_xuat_id, chung_tu_hoan_thanh_sx_id, chi_tiet_phieu_dieu_chinh_id) = 1),
  CONSTRAINT "ck_giao_dich_loai_dau" CHECK ((loai_giao_dich = 'nhap_vat_tu' AND chi_tiet_phieu_nhap_id IS NOT NULL AND so_luong_bien_dong > 0) OR (loai_giao_dich IN ('xuat_vat_tu','xuat_thanh_pham') AND chi_tiet_phieu_xuat_id IS NOT NULL AND so_luong_bien_dong < 0) OR (loai_giao_dich = 'nhap_san_pham_san_xuat' AND chung_tu_hoan_thanh_sx_id IS NOT NULL AND so_luong_bien_dong > 0) OR (loai_giao_dich = 'dieu_chinh_ton_kho' AND chi_tiet_phieu_dieu_chinh_id IS NOT NULL AND so_luong_bien_dong <> 0))
);

CREATE TABLE "LichSuThaoTac" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nhan_vien_id" int NOT NULL,
  "loai_doi_tuong" varchar NOT NULL,
  "doi_tuong_id" int NOT NULL,
  "thao_tac" varchar NOT NULL,
  "du_lieu_truoc" jsonb,
  "du_lieu_sau" jsonb,
  "ly_do" text,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  CONSTRAINT "ck_lich_su_thao_tac_loai_doi_tuong" CHECK (loai_doi_tuong IN ('nhan_vien', 'vai_tro', 'mat_hang', 'nha_cung_cap', 'cong_thuc', 'phieu_nhap', 'phieu_xuat', 'yeu_cau_san_xuat', 'lenh_san_xuat', 'chung_tu_hoan_thanh_san_xuat', 'phieu_dieu_chinh_kho', 'ticket_loi_dieu_chinh')),
  CONSTRAINT "ck_lich_su_thao_tac_thao_tac" CHECK (thao_tac IN ('tao', 'sua', 'xoa_nhap', 'gui', 'bat_dau', 'duyet', 'tu_choi', 've_nhap', 'hoan_tat', 'cap_quyen', 'thu_hoi_quyen', 'vo_hieu_hoa', 'huy', 'ghi_nhan_loi', 'nhan_xu_ly', 'giai_quyet', 'xac_nhan', 'dang_nhap'))
);

CREATE TABLE "LuuLuongTruyCap" (
  "gio_bat_dau" timestamptz PRIMARY KEY,
  "so_request" bigint NOT NULL DEFAULT 0,
  CONSTRAINT "ck_luu_luong_truy_cap_so_request" CHECK (so_request >= 0)
);

CREATE UNIQUE INDEX ON "Bom" ("mat_hang_id", "version");

CREATE UNIQUE INDEX ON "ChiTietBom" ("bom_id", "mat_hang_id");

CREATE UNIQUE INDEX ON "ChiTietPhieuNhap" ("phieu_nhap_id", "mat_hang_id");

CREATE UNIQUE INDEX ON "ChiTietPhieuXuat" ("phieu_xuat_id", "mat_hang_id");

CREATE UNIQUE INDEX ON "ChiTietLenhSanXuat" ("lenh_san_xuat_id", "mat_hang_id");

CREATE UNIQUE INDEX ON "ChiTietPhieuDieuChinhKho" ("phieu_dieu_chinh_kho_id", "giao_dich_goc_id");

CREATE UNIQUE INDEX ON "ChiTietTicketLoiDieuChinh" ("ticket_id", "chi_tiet_phieu_nhap_id");

CREATE INDEX ON "GiaoDichKho" ("mat_hang_id", "posted_at");

CREATE INDEX ON "LichSuThaoTac" ("loai_doi_tuong", "doi_tuong_id", "created_at");

CREATE INDEX ON "LichSuThaoTac" ("nhan_vien_id", "created_at");

COMMENT ON COLUMN "NhanVien"."mat_khau" IS 'Chỉ lưu hash mật khẩu; seed dùng bcrypt. Không lưu mật khẩu rõ.';

COMMENT ON COLUMN "NhanVien"."ma_nhan_vien" IS 'Định dạng: NV-NNNNNN; sinh một lần, không tái sử dụng.';

COMMENT ON COLUMN "NhanVien"."trang_thai" IS 'hoat_dong / bi_khoa';

COMMENT ON COLUMN "VaiTro"."ma_vai_tro" IS 'nhan_vien / quan_ly / quan_tri_vien';

COMMENT ON COLUMN "VaiTro"."mo_ta" IS 'Mô tả phạm vi của vai trò, hiển thị trên ADM-04. Chỉ đọc qua API; bộ vai trò cố định 3 mã.';

COMMENT ON TABLE "MatHang" IS 'loai_mat_hang: nguyen_vat_lieu / linh_kien / ban_thanh_pham / thanh_pham. V3.1 gộp số dư tồn vào MatHang. Cập nhật số dư, giao dịch kho, chứng từ và audit cùng transaction; khóa dòng MatHang hoặc UPDATE có điều kiện khi xuất kho.';

COMMENT ON COLUMN "MatHang"."so_luong_ton" IS 'Số dư tồn hiện tại, chuyển từ TonKho.so_luong. GiaoDichKho giữ lịch sử biến động để đối soát.';

COMMENT ON COLUMN "MatHang"."ton_kho_updated_at" IS 'Thời điểm cập nhật số dư tồn gần nhất, chuyển từ TonKho.updated_at; backend cập nhật khi ghi sổ.';

COMMENT ON COLUMN "MatHang"."ma_mat_hang" IS 'Định dạng: MH-NNNNNN; sinh một lần, không tái sử dụng.';

COMMENT ON COLUMN "MatHang"."loai_mat_hang" IS 'Miền giá trị: nguyen_vat_lieu / linh_kien / ban_thanh_pham / thanh_pham.';

COMMENT ON COLUMN "MatHang"."don_vi_tinh" IS 'Danh mục mở, mã snake_case không dấu; ví dụ: chiec / bo / met / kilogam.';

COMMENT ON COLUMN "MatHang"."mau_sac" IS 'Danh mục mở, mã snake_case không dấu; ví dụ: do / tim / vang / den / trang.';

COMMENT ON TABLE "Bom" IS 'Mỗi BOM mô tả một đơn vị đầu ra; version > 0.
Mỗi mặt hàng chỉ có tối đa một BOM hiện hành.
BOM và chi tiết đã được lệnh sử dụng không được sửa/xóa; tạo version mới.
Không cho phép chu trình trực tiếp hoặc gián tiếp trong cấu trúc BOM.
BOM con được chọn và khóa bằng bom_id của từng lệnh con.
';

COMMENT ON TABLE "ChiTietBom" IS 'CHECK (so_luong > 0). Thành phần có thể là NVL, linh_kien hoặc bán thành phẩm có BOM riêng.';

