CREATE INDEX ix_ticket_trang_thai ON "TicketLoiDieuChinh"(trang_thai, created_at);

-- Không tự cộng/trừ MatHang.so_luong_ton: backend phải cập nhật số dư, ton_kho_updated_at, giao dịch, chứng từ và audit cùng transaction.
CREATE FUNCTION kiem_tra_nguon_giao_dich() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE v_mat_hang int; v_luong int; v_trang_thai text; v_loai text;
BEGIN
  CASE
  WHEN NEW.chi_tiet_phieu_nhap_id IS NOT NULL THEN
    SELECT c.mat_hang_id, c.so_luong, p.trang_thai INTO v_mat_hang,v_luong,v_trang_thai
    FROM "ChiTietPhieuNhap" c JOIN "PhieuNhap" p ON p.id=c.phieu_nhap_id
    WHERE c.id=NEW.chi_tiet_phieu_nhap_id;
    IF v_trang_thai IS DISTINCT FROM 'hoan_thanh' THEN
      RAISE EXCEPTION 'Phiếu nhập chưa hoàn tất hoặc không tồn tại'; END IF;
    IF NOT EXISTS (SELECT 1 FROM "MatHang" WHERE id=v_mat_hang AND loai_mat_hang IN ('nguyen_vat_lieu','linh_kien')) THEN
      RAISE EXCEPTION 'Phiếu nhập chỉ hỗ trợ NVL/linh kiện'; END IF;
  WHEN NEW.chi_tiet_phieu_xuat_id IS NOT NULL THEN
    SELECT c.mat_hang_id,-c.so_luong,p.trang_thai,p.loai_phieu INTO v_mat_hang,v_luong,v_trang_thai,v_loai
    FROM "ChiTietPhieuXuat" c JOIN "PhieuXuat" p ON p.id=c.phieu_xuat_id
    WHERE c.id=NEW.chi_tiet_phieu_xuat_id;
    IF v_trang_thai IS DISTINCT FROM 'da_duyet' OR v_loai IS DISTINCT FROM NEW.loai_giao_dich THEN
      RAISE EXCEPTION 'Phiếu xuất chưa duyệt hoặc sai loại giao dịch'; END IF;
  WHEN NEW.chung_tu_hoan_thanh_sx_id IS NOT NULL THEN
    SELECT l.mat_hang_id,c.so_luong_hoan_thanh,c.trang_thai INTO v_mat_hang,v_luong,v_trang_thai
    FROM "ChungTuHoanThanhSx" c JOIN "LenhSanXuat" l ON l.id=c.lenh_san_xuat_id
    WHERE c.id=NEW.chung_tu_hoan_thanh_sx_id;
    IF v_trang_thai IS DISTINCT FROM 'da_duyet' THEN
      RAISE EXCEPTION 'Chứng từ hoàn thành chưa duyệt'; END IF;
  WHEN NEW.chi_tiet_phieu_dieu_chinh_id IS NOT NULL THEN
    SELECT c.mat_hang_id,c.so_luong_bien_dong,p.trang_thai INTO v_mat_hang,v_luong,v_trang_thai
    FROM "ChiTietPhieuDieuChinhKho" c JOIN "PhieuDieuChinhKho" p ON p.id=c.phieu_dieu_chinh_kho_id
    WHERE c.id=NEW.chi_tiet_phieu_dieu_chinh_id;
    IF v_trang_thai IS DISTINCT FROM 'da_xac_nhan' THEN
      RAISE EXCEPTION 'Phiếu điều chỉnh chưa xác nhận'; END IF;
  ELSE RAISE EXCEPTION 'Giao dịch thiếu chứng từ nguồn';
  END CASE;
  IF NEW.mat_hang_id IS DISTINCT FROM v_mat_hang OR NEW.so_luong_bien_dong IS DISTINCT FROM v_luong THEN
    RAISE EXCEPTION 'Mặt hàng hoặc lượng giao dịch không khớp chứng từ nguồn'; END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER trg_giao_dich_nguon BEFORE INSERT ON "GiaoDichKho"
FOR EACH ROW EXECUTE FUNCTION kiem_tra_nguon_giao_dich();

CREATE FUNCTION kiem_tra_nguon_dieu_chinh() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM "GiaoDichKho" g
    JOIN "ChiTietPhieuNhap" n ON n.id=g.chi_tiet_phieu_nhap_id
    JOIN "PhieuNhap" pn ON pn.id=n.phieu_nhap_id
    JOIN "PhieuDieuChinhKho" p ON p.id=NEW.phieu_dieu_chinh_kho_id
    WHERE g.id=NEW.giao_dich_goc_id AND g.loai_giao_dich='nhap_vat_tu'
      AND g.mat_hang_id=NEW.mat_hang_id AND n.mat_hang_id=NEW.mat_hang_id
      AND p.phieu_nhap_id=n.phieu_nhap_id AND pn.trang_thai='hoan_thanh'
  ) THEN RAISE EXCEPTION 'Điều chỉnh phải trỏ giao dịch nhập của đúng phiếu nhập, mặt hàng'; END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER trg_dieu_chinh_nguon BEFORE INSERT OR UPDATE ON "ChiTietPhieuDieuChinhKho"
FOR EACH ROW EXECUTE FUNCTION kiem_tra_nguon_dieu_chinh();

CREATE FUNCTION kiem_tra_nguon_ticket() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM "ChiTietPhieuNhap" c JOIN "TicketLoiDieuChinh" t ON t.id=NEW.ticket_id
    JOIN "PhieuNhap" p ON p.id=t.phieu_nhap_id
    WHERE c.id=NEW.chi_tiet_phieu_nhap_id AND c.phieu_nhap_id=t.phieu_nhap_id
      AND c.mat_hang_id=NEW.mat_hang_id AND p.trang_thai='hoan_thanh'
  ) THEN RAISE EXCEPTION 'Dòng ticket không thuộc đúng phiếu nhập hoàn tất và mặt hàng'; END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER trg_ticket_nguon BEFORE INSERT ON "ChiTietTicketLoiDieuChinh"
FOR EACH ROW EXECUTE FUNCTION kiem_tra_nguon_ticket();

CREATE FUNCTION chan_sua_lich_su() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN RAISE EXCEPTION 'Không được sửa/xóa lịch sử đã ghi nhận: %', TG_TABLE_NAME; END $$;
CREATE TRIGGER trg_giao_dich_bat_bien BEFORE UPDATE OR DELETE ON "GiaoDichKho"
FOR EACH ROW EXECUTE FUNCTION chan_sua_lich_su();
CREATE TRIGGER trg_audit_bat_bien BEFORE UPDATE OR DELETE ON "LichSuThaoTac"
FOR EACH ROW EXECUTE FUNCTION chan_sua_lich_su();
CREATE TRIGGER trg_ticket_chi_tiet_bat_bien BEFORE UPDATE OR DELETE ON "ChiTietTicketLoiDieuChinh"
FOR EACH ROW EXECUTE FUNCTION chan_sua_lich_su();

CREATE FUNCTION bao_ve_ticket() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Không được xóa ticket'; END IF;
  IF OLD.trang_thai='da_xu_ly' THEN RAISE EXCEPTION 'Ticket đã đóng không được sửa/mở lại'; END IF;
  IF ROW(NEW.id,NEW.ma_ticket,NEW.phieu_nhap_id,NEW.nguoi_tao_id,NEW.mo_ta_loi,NEW.created_at)
     IS DISTINCT FROM ROW(OLD.id,OLD.ma_ticket,OLD.phieu_nhap_id,OLD.nguoi_tao_id,OLD.mo_ta_loi,OLD.created_at)
  THEN RAISE EXCEPTION 'Không được thay đổi bối cảnh ticket ban đầu'; END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER trg_ticket_boi_canh BEFORE UPDATE OR DELETE ON "TicketLoiDieuChinh"
FOR EACH ROW EXECUTE FUNCTION bao_ve_ticket();

CREATE FUNCTION bao_ve_chung_tu() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF OLD.trang_thai=ANY(string_to_array(TG_ARGV[0],',')) THEN
    RAISE EXCEPTION 'Chứng từ đã chốt không được sửa/xóa: %',TG_TABLE_NAME; END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER trg_nhap_bat_bien BEFORE UPDATE OR DELETE ON "PhieuNhap"
FOR EACH ROW EXECUTE FUNCTION bao_ve_chung_tu('hoan_thanh');
CREATE TRIGGER trg_xuat_bat_bien BEFORE UPDATE OR DELETE ON "PhieuXuat"
FOR EACH ROW EXECUTE FUNCTION bao_ve_chung_tu('da_duyet');
CREATE TRIGGER trg_hoan_thanh_bat_bien BEFORE UPDATE OR DELETE ON "ChungTuHoanThanhSx"
FOR EACH ROW EXECUTE FUNCTION bao_ve_chung_tu('da_duyet');
CREATE TRIGGER trg_dieu_chinh_bat_bien BEFORE UPDATE OR DELETE ON "PhieuDieuChinhKho"
FOR EACH ROW EXECUTE FUNCTION bao_ve_chung_tu('da_xac_nhan,loi');

-- Chặn thêm, sửa hoặc chuyển dòng ra/vào một chứng từ đã chốt.
CREATE FUNCTION bao_ve_dong_chung_tu() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE v_id int; v_state text; v_ids int[] := '{}';
BEGIN
  IF TG_OP<>'INSERT' THEN v_ids := array_append(v_ids,(to_jsonb(OLD)->>TG_ARGV[1])::int); END IF;
  IF TG_OP<>'DELETE' THEN v_ids := array_append(v_ids,(to_jsonb(NEW)->>TG_ARGV[1])::int); END IF;
  FOREACH v_id IN ARRAY v_ids LOOP
    EXECUTE format('SELECT trang_thai FROM %I WHERE id=$1 FOR UPDATE',TG_ARGV[0]) INTO v_state USING v_id;
    IF v_state=ANY(string_to_array(TG_ARGV[2],',')) THEN
      RAISE EXCEPTION 'Không được thay đổi dòng của chứng từ đã chốt'; END IF;
  END LOOP;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER trg_dong_nhap_bat_bien BEFORE INSERT OR UPDATE OR DELETE ON "ChiTietPhieuNhap"
FOR EACH ROW EXECUTE FUNCTION bao_ve_dong_chung_tu('PhieuNhap','phieu_nhap_id','hoan_thanh');
CREATE TRIGGER trg_dong_xuat_bat_bien BEFORE INSERT OR UPDATE OR DELETE ON "ChiTietPhieuXuat"
FOR EACH ROW EXECUTE FUNCTION bao_ve_dong_chung_tu('PhieuXuat','phieu_xuat_id','da_duyet');
CREATE TRIGGER trg_dong_dieu_chinh_bat_bien BEFORE INSERT OR UPDATE OR DELETE ON "ChiTietPhieuDieuChinhKho"
FOR EACH ROW EXECUTE FUNCTION bao_ve_dong_chung_tu('PhieuDieuChinhKho','phieu_dieu_chinh_kho_id','da_xac_nhan,loi');

CREATE FUNCTION bao_ve_bom_da_dung() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE v_old int; v_new int;
BEGIN
  IF TG_TABLE_NAME='Bom' THEN
    v_old := OLD.id;
    IF EXISTS (SELECT 1 FROM "LenhSanXuat" WHERE bom_id=v_old) THEN
      IF TG_OP='DELETE' THEN RAISE EXCEPTION 'BOM đã dùng không được xóa'; END IF;
      -- Cho phép đóng hiệu lực để mở phiên bản mới; không sửa định danh/đầu ra/version.
      IF ROW(NEW.id,NEW.mat_hang_id,NEW.version,NEW.start_time) IS DISTINCT FROM
         ROW(OLD.id,OLD.mat_hang_id,OLD.version,OLD.start_time) THEN
        RAISE EXCEPTION 'BOM đã dùng chỉ được đóng/mở hiệu lực'; END IF;
    END IF;
  ELSE
    IF TG_OP<>'INSERT' THEN v_old:=OLD.bom_id; END IF;
    IF TG_OP<>'DELETE' THEN v_new:=NEW.bom_id; END IF;
    -- Cùng khóa BOM với thao tác tạo lệnh để backend có thể tuần tự hóa.
    PERFORM 1 FROM "Bom" WHERE id IN (v_old,v_new) ORDER BY id FOR UPDATE;
    IF EXISTS (SELECT 1 FROM "LenhSanXuat" WHERE bom_id IN (v_old,v_new)) THEN
      RAISE EXCEPTION 'Không được thay đổi thành phần BOM đã dùng'; END IF;
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER trg_bom_bao_ve BEFORE UPDATE OR DELETE ON "Bom"
FOR EACH ROW EXECUTE FUNCTION bao_ve_bom_da_dung();
CREATE TRIGGER trg_bom_dong_bao_ve BEFORE INSERT OR UPDATE OR DELETE ON "ChiTietBom"
FOR EACH ROW EXECUTE FUNCTION bao_ve_bom_da_dung();

COMMIT;
